package com.wizzadrds.theworldremembers.dream; import com.wizzadrds.theworldremembers.memory.*; import com.wizzadrds.theworldremembers.stress.NpcStressManager; import java.util.*; public final class DreamSelector{public Optional<Dream> select(UUID npc,long cycle,MemoryManager memories,NpcStressManager stress){var m=memories.memoriesOf(npc);if(stress.value(npc)>=60){var x=m.stream().filter(v->v.type()==MemoryEventType.PLAYER_ATTACKED_NPC||v.type()==MemoryEventType.PLAYER_THREATENED_NPC||v.type()==MemoryEventType.NPC_FAMILY_LOST||v.type()==MemoryEventType.NPC_DIED).max(Comparator.comparingLong(Memory::gameTime));if(x.isPresent())return Optional.of(make(npc,DreamType.FEAR,x.get().summary(),cycle));}var n=m.stream().filter(v->v.type()==MemoryEventType.NPC_BORN||v.type()==MemoryEventType.NPC_MARRIED||v.type()==MemoryEventType.NPC_FAMILY_LOST||v.type()==MemoryEventType.NPC_INHERITED_ITEM).max(Comparator.comparingLong(Memory::gameTime));if(n.isPresent())return Optional.of(make(npc,DreamType.NOSTALGIA,n.get().summary(),cycle));var r=m.stream().filter(v->v.importance().ordinal()>=MemoryImportance.IMPORTANT.ordinal()).max(Comparator.comparingLong(Memory::gameTime));if(r.isPresent())return Optional.of(make(npc,DreamType.MEMORY,r.get().summary(),cycle));return Optional.of(make(npc,DreamType.IMPOSSIBLE,"a world shaped by impossible memories",cycle));}private Dream make(UUID id,DreamType type,String source,long cycle){return new Dream(id,type,source,id.getMostSignificantBits()^Long.rotateLeft(id.getLeastSignificantBits(),17)^cycle*0x9E3779B97F4A7C15L);}}
